    {
      "poi_id": "p4",
      "kind": "activity",
      "must_do_id": null,
      "note": "A free taste of local life and street snacks, perfect for a thrifty crew."
    },
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": null,
      "note": "Free history and a fine photo spot in the heart of the plaza."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch at the budget-friendly pizzeria, easy on the wallet and the pace."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "A lower-priced stop that swaps the cathedral for something sweeter and still local."
    },
    {
      "poi_id": "p17",
